package core

import (
	"regexp"
	"strings"
	"unicode"
)

var slugifyNonWordRegex = regexp.MustCompile(`[^\w\-]+`)
var slugifyMultiHyphenRegex = regexp.MustCompile(`-{2,}`)

// Slugify converts the provided string into a URL-friendly slug.
//
// It lowercases the string, replaces spaces with hyphens, removes
// non-alphanumeric characters (except hyphens), and collapses
// consecutive hyphens into a single one.
//
// For example:
//
//	core.Slugify("Hello World!") // "hello-world"
func Slugify(str string) string {
	str = strings.TrimSpace(strings.ToLower(str))

	// replace spaces with hyphens
	str = strings.ReplaceAll(str, " ", "-")

	var result strings.Builder
	for _, r := range str {
		if unicode.IsLetter(r) || unicode.IsNumber(r) || r == '-' {
			result.WriteRune(r)
		} else {
			result.WriteRune('-')
		}
	}

	slug := result.String()

	// collapse multiple consecutive hyphens
	slug = slugifyMultiHyphenRegex.ReplaceAllString(slug, "-")

	// remove any remaining non-word characters that were converted to hyphens
	slug = slugifyNonWordRegex.ReplaceAllString(slug, "-")

	// collapse again after the replacement
	slug = slugifyMultiHyphenRegex.ReplaceAllString(slug, "-")

	// trim leading/trailing hyphens
	slug = strings.Trim(slug, "-")

	return slug
}

package main

import (
	"log"

	"github.com/pocketbase/pocketbase"
	"github.com/pocketbase/pocketbase/core"
)

func main() {
	app := pocketbase.New()

	app.OnRecordCreateRequest("posts").BindFunc(func(e *core.RecordRequestEvent) error {
		title := e.Record.GetString("title")
		if title == "" {
			return e.BadRequestError("Title cannot be empty", nil)
		}

		slug := core.Slugify(title)
		e.Record.Set("slug", slug)

		return e.Next()
	})

	if err := app.Start(); err != nil {
		log.Fatal(err)
	}
}
